                    // merge them. This makes \`.route("/", get(_)).route("/", post(_))\` work
                    let service =
                        Endpoint::MethodRouter(prev_method_router.clone().merge(method_router));
                    self.routes.insert(route_id, service);
                    return self;
                } else {

                Endpoint::MethodRouter(method_router)
            }
            Err(svc) => Endpoint::Route(svc),
        };

        self.routes.insert(id, service);
        self.node.insert(path, id)?;

        self
    }

    #[doc = include_str!("../docs/routing/nest.md")]
    pub fn nest<B, E>(mut self, path: &str, router: Router<B>) -> Self
    where
        B: HttpBody + Send + 'static,
        E: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        E::Future: Send + 'static,
    {
