            Ok(_) => {
                panic!("Invalid route: \`Router::nest\` cannot be used with \`Router\`s. Use \`Router::nest\` instead")
            }
            Err(svc) => svc,
        };

        let service = Endpoint::Route(service);

        self.routes.insert(id, service);
        self.node.insert(path, id)?;

        let path_str = path.to_owned();
        let mut nested_at_root = self.nested_at_root;
