        let mut node = self.node;
        let mut fallback = self.fallback;
        let nested_at_root = self.nested_at_root;

        for (id, endpoint) in other.routes {
            if let Some((route_id, Endpoint::MethodRouter(other_method_router))) = node
                .path_to_route_id
                .get(&other.node.route_id_to_path[&id].to_string())
                .and_then(|route_id| routes.get(route_id).map(|svc| (*route_id, svc)))
            {
                if let (Endpoint::MethodRouter(prev_method_router), Endpoint::MethodRouter(other_method_router)) =
                    (svc, endpoint)
                {
                    routes.insert(route_id, Endpoint::MethodRouter(prev_method_router.clone().merge(other_method_router)));
                } else {
                    panic!("Cannot merge two routes that have different endpoint types");
                }
            } else {
                routes.insert(id, endpoint);
                node.insert(&other.node.route_id_to_path[&id].to_string(), id).unwrap();
            }
        }

        // This is a bit simplified, but it should work for most cases.
        // A more complete implementation would merge the nodes.
        // For now, we'll just assume that the nodes can be merged.
        // This is a known limitation of the current implementation.

        Router {
            routes,
            node,
            fallback,
            nested_at_root,
        }
    }

    #[doc = include_str!("../docs/routing/fallback.md")]
    pub fn fallback<F, B2, E2>(self, fallback: F) -> Self
    where
        F: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        F::Future: Send + 'static,
        B2: HttpBody + Send + 'static,
        E2: Infallible,
    {
