            Ok(_) => {
                panic!("Invalid route: `Router::fallback` cannot be used with `Router`s. Use `Router::nest` instead")
            }
            Err(svc) => svc,
        };

        let id = RouteId::next();
        let service = Endpoint::Route(service);

        self.routes.insert(id, service);
        self.node.insert("/", id).unwrap();

        Router {
            routes: self.routes,
            node: self.node,
            fallback: Fallback::Custom(Route::new(service)),
            nested_at_root: self.nested_at_root,
        }
    }
